head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst10000";
scwin.fnBookmarkSearch = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $c.util.getComponent("tabContents").setStyle("display", "none");
        /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
        if (($c.util.getComponent('AKCKwd').getValue() === null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
            await scwin.fnSearchCorpBasicInfo('');
        } else {
            await scwin.fnInitComNmSetting();
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst10000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.fnBookmarkSearch = fnBookmarkSearch;
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst10000.onpageload' });
    }
};

