///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            if (fnAKCKwdSearchCodeType(($c.util.getComponent('AKCKwd')))) {
                await scwin.fnSearchCorpBasicInfo('');
            }
        }
    }
};

/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function () {
    await scwin.fnSearchCorpBasicInfo('');
};

/**
 * @method
 * @name fnTabView
 * @description fn Tab View 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnTabView = async function (idx) {
    $(document).find("li[name=tabView]").each(function(index) {
            if (idx === index) {
                if (!$('#tabView_' + idx).hasClass("active")) {
                    $('#tabView_' + idx).addClass("active");
                }
            } else {
                if ($('#tabView_' + index).hasClass("active")) {
                    $('#tabView_' + index).removeClass("active");
                }
            }
    });
    $c.util.getComponent("dma_fnSearchReq").set("tabMenu", idx);
    $c.util.getComponent("dma_fnSearchReq").set("mode", "");
    await scwin.fnSearch('tab');
};

/**
 * @method
 * @name fnInitComNmSetting
 * @description fn Init Com Nm Setting 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInitComNmSetting = async function () {
    const comnm = scwin.fnGetRecentCompanyFromCookie();
    if (comnm !== null && comnm !== "") {
        $c.util.getComponent('AKCKwd').setValue(comnm);
        await scwin.fnSearchCorpBasicInfo('');
    }
};

/**
 * @method
 * @name fnGetRecentCompanyFromCookie
 * @description fn Get Recent Company From Cookie 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnGetRecentCompanyFromCookie = function () {
    const cookies = scwin.fnGetCookie('krxComp');
    const item = null;
    let userCompaniesArray = null;
    let tmpstr = null;
    if (cookies !== null) {
        userCompaniesArray = cookies.split("/");
    }
    const issues = "";
    tmpstr = "";
    if (userCompaniesArray !== null && userCompaniesArray !== "") {
        tmpstr = userCompaniesArray[0].split(",");
    }
    return tmpstr[2];
};

/**
 * @method
 * @name fnSearchCorpBasicInfo
 * @description fn Search Corp Basic Info 처리
 * @param {*} ipt_mode ipt_mode
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpBasicInfo = async function (ipt_mode) {
    let cd_or_nm = $c.util.getComponent('AKCKwd').getValue(); if (cd_or_nm === null) { cd_or_nm = ''; }
    if (cd_or_nm === null || cd_or_nm === "") {
        await $c.win.alert("회사명 또는 종목코드를 입력해 주세요.");
        return;
    }
    $c.util.getComponent("dma_fnSearchReq").set("isurCd", "");
    $c.util.getComponent("dma_fnSearchReq").set("kisComCd", "");
    $c.util.getComponent("dma_fnSearchReq").set("repIsuCd", "");
    if (ipt_mode === 'print') {
        $c.util.getComponent("dma_fnSearchReq").set("mode", "print");
    } else {
        $c.util.getComponent("dma_fnSearchReq").set("mode", "");
    }
    $c.util.getComponent("dma_fnSearchReq").set("searchCorpName", cd_or_nm);
    Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
};

/**
 * @method
 * @name fnSearchCorpNameAllCallBack
 * @description fn Search Corp Name All Call Back 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    if (items.length === 1) {
        await scwin.fnSetCorpBasicInfo(items[0]);
    } else {
        if (items.length > 1) {
            Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    } else {
        await scwin.fnSetCorpBasicInfo(null);
    }
}
};

/**
 * @method
 * @name fnSetCorpBasicInfo
 * @description fn Set Corp Basic Info 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSetCorpBasicInfo = async function (items) {
    if (items === null) {
        const val = ($c.util.getComponent("dma_fnSearchReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
        $c.util.getComponent("dma_fnSearchReq").set("isurCd", "");
        $c.util.getComponent("dma_fnSearchReq").set("kisComCd", "");
        $c.util.getComponent("dma_fnSearchReq").set("repIsuCd", "");
        $c.util.getComponent("dma_fnSearchReq").set("comAttrTpCd", "");
        $c.util.getComponent('AKCKwd').setValue("");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
    } else {
        const isurcd = $c.util.getComponent('ipt_isurCd');
        const kiscomcd = $c.util.getComponent('ipt_kisComCd');
        const repisucd = $c.util.getComponent('ipt_repIsuCd');
        const comabbr = items.comabbrv;
        const mkttpcd = $c.util.getComponent('ipt_spotIsuTrdMktTpCd');
        const comAttrTpCd = items.comAttrTpCd;
        $c.util.getComponent("dma_fnSearchReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnSearchReq").set("kisComCd", kiscomcd);
        $c.util.getComponent("dma_fnSearchReq").set("repIsuCd", repisucd);
        $c.util.getComponent("dma_fnSearchReq").set("spotIsuTrdMktTpCd", mkttpcd);
        $c.util.getComponent("dma_fnSearchReq").set("comAttrTpCd", comAttrTpCd);
        $c.util.getComponent('AKCKwd').setValue(comabbr);
        await scwin.fnSearch();
    }
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @param {*} type type
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function (type) {
    void("fnSearch : " + type);
    let comAbbrv = $c.util.getComponent('AKCKwd').getValue(); if (comAbbrv === null) { comAbbrv = ''; }
    if (comAbbrv === null || comAbbrv === "") {
        await $c.win.alert("회사명을 입력해 주세요.");
        return;
    }
    /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
    $c.util.getComponent("tabContents").setStyle("display", "");
    const comAttrTpCd = ($c.util.getComponent("dma_fnSearchReq").get("comAttrTpCd") || '');
    void("comAttrTpCd : " + comAttrTpCd);
