/**
 * @method
 * @name fnBookmark
 * @description fn Bookmark 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnBookmark = function () {
    const cookieName = "krxComp";
    const cookies = $c.util.getSessionStorage(cookieName);
    if (cookies !== null) {
        (($c.util.getComponent('txt_myBookmark')) && ($c.util.getComponent('txt_myBookmark')).removeAll ? ($c.util.getComponent('txt_myBookmark')).removeAll() : (($c.util.getComponent('txt_myBookmark')) && ($c.util.getComponent('txt_myBookmark')).setValue ? ($c.util.getComponent('txt_myBookmark')).setValue('') : void 0));
        const items = cookies.split("/");
        let max = 0;
        for (i in items) {
            if (max === 10) {
                break;
            }
            const item = items[i].split(",");
            const repIsuSrtCd = item[1];
            const corpName = item[2];
            const isurcd = item[3];
            if (undefined !== corpName && undefined !== isurcd) {
                $("#txt_myBookmark").append("<a href='#' onclick=\"fnBookmarkSearch('" + repIsuSrtCd + "','" + corpName + "'); return false;\" title=\"" + corpName + " 검색\" >" + corpName + "</a> ");
            }
            max++;
        }
    }
};

async function fnBookmarkSearch(repIsuSrtCd, corpName) {
    $c.util.getComponent('AKCKwd').setValue(corpName);
    await scwin.fnSearchCorpBasicInfo('');
}

